[tasks.collect]
shell = "node --input-type=module-typescript -e"
run = '''
const {execFileSync} = await import('node:child_process');
const {mkdirSync,writeFileSync,readFileSync} = await import('node:fs');
const {createHash} = await import('node:crypto');
const {join} = await import('node:path');
const runId=process.env.DEPOT_ACCOUNTING_RUN;
if(!runId || !/^[a-z0-9]+$/.test(runId))throw new Error('DEPOT_ACCOUNTING_RUN must name one run');
const org=process.env.DEPOT_ACCOUNTING_ORG??'l4zncjjbj5';
const dir=join(process.cwd(),`collected-${runId}`);
mkdirSync(dir,{recursive:true,mode:0o700});
const get=(args,name)=>{
  const raw=execFileSync('depot',[...args,'--org',org,'--output','json'],{encoding:'utf8',maxBuffer:64*1024*1024});
  writeFileSync(join(dir,name),raw);
  return JSON.parse(raw);
};
const status=get(['ci','status',runId],'status.json');
const run=get(['ci','run','show',runId],'run.json');
const expected=process.env.DEPOT_ACCOUNTING_SHA;
const actual=run.head_sha??run.run?.head_sha??run.sha??run.run?.sha;
if(expected && actual!==expected)throw new Error(`Run revision differs: expected ${expected}, got ${actual}`);
const attempts=[];
for(const workflow of status.workflows??[])for(const job of workflow.jobs??[])for(const attempt of job.attempts??[]){
  if(attempts.some(row=>row.attemptId===attempt.attempt_id))throw new Error(`Repeated attempt ${attempt.attempt_id}`);
  const metrics=get(['ci','metrics',attempt.attempt_id],`metrics-${attempt.attempt_id}.json`);
  const logPath=join(dir,`logs-${attempt.attempt_id}.jsonl`);
  execFileSync('depot',['ci','logs',attempt.attempt_id,'--org',org,'--output','json','--output-file',logPath],{encoding:'utf8',maxBuffer:1024*1024});
  const raw=readFileSync(logPath);
  const lines=raw.toString().split('\n').filter(Boolean).map(line=>JSON.parse(line));
  attempts.push({workflowId:workflow.workflow_id,jobId:job.job_id,jobKey:job.job_key,attemptId:attempt.attempt_id,attempt:attempt.attempt,status:attempt.status,metricsPath:`metrics-${attempt.attempt_id}.json`,logPath:`logs-${attempt.attempt_id}.jsonl`,logSha256:createHash('sha256').update(raw).digest('hex'),logRecords:lines.length,providerAttempt:metrics.attempt?.attempt??metrics.attempt});
}
const artifacts=get(['ci','artifacts','list',runId],'artifacts.json');
const summary={collectedAt:new Date().toISOString(),org,runId,revision:actual,status:status.status,attempts,artifactCount:artifacts.artifacts?.length??0,scope:'Read-only collection. Provider intervals require declared resources before pricing. Gate completion needs independent manifest reconciliation.'};
writeFileSync(join(dir,'collection.json'),JSON.stringify(summary,null,2)+'\n');
console.log(JSON.stringify({runId,revision:actual,attempts:attempts.length,artifactCount:summary.artifactCount,dir}));
'''

[tasks.analyze]
shell = "node --input-type=module-typescript -e"
run = '''
const {readFileSync,writeFileSync} = await import('node:fs');
const {createHash} = await import('node:crypto');
const inputPath=process.env.DEPOT_ACCOUNTING_INPUT;
if(!inputPath)throw new Error('DEPOT_ACCOUNTING_INPUT must name normalized evidence');
const raw=readFileSync(inputPath);
const input=JSON.parse(raw);
const instant=value=>{
  const parsed=Date.parse(value);
  if(!Number.isFinite(parsed))throw new Error(`Invalid timestamp ${value}`);
  return parsed;
};
const unique=(rows,label)=>{
  const ids=rows.map(row=>row.id);
  if(new Set(ids).size!==ids.length)throw new Error(`Duplicate ${label} identity`);
};
const union=intervals=>{
  const ordered=intervals.toSorted((a,b)=>a[0]-b[0]);
  let total=0,end=-Infinity;
  for(const [start,stop]of ordered){
    if(stop<start)throw new Error('Negative interval');
    total+=Math.max(0,stop-Math.max(start,end));
    end=Math.max(end,stop);
  }
  return total/1000;
};
const evaluate=evidence=>{
  if(!/^[a-f0-9]{40}$/.test(evidence.revision))throw new Error('Immutable revision required');
  if(evidence.manifest.length===0)throw new Error('Trial manifest cannot be empty');
  unique(evidence.manifest,'manifest');unique(evidence.checks,'check');unique(evidence.attempts,'attempt');
  const selection=evidence.selection;
  if(!selection||!/^[a-f0-9]{40}$/.test(selection.base)||selection.head!==evidence.revision)throw new Error('Frozen change-selection base/head required');
  if(!Array.isArray(selection.changedFiles)||!Array.isArray(selection.affectedPackages)||!Array.isArray(selection.excludedPackages))throw new Error('Selection inventory required');
  if(!/^[a-f0-9]{64}$/.test(selection.manifestSha256))throw new Error('Manifest fingerprint required');
  if(selection.affectedPackages.some(path=>selection.excludedPackages.includes(path)))throw new Error('Affected package also excluded');
  const actualIds=evidence.manifest.map(row=>row.id).toSorted();
  if(JSON.stringify(actualIds)!==JSON.stringify([...selection.selectedCheckIds].toSorted()))throw new Error('Manifest differs from selected required checks');
  for(const spec of evidence.manifest){
    const packages=spec.packages??[spec.packagePath];
    if(spec.scope==='files'){
      if(!spec.files?.length||spec.files.some(path=>!selection.changedFiles.includes(path)))throw new Error(`File check outside changed input ${spec.id}`);
    }else if(spec.scope==='repository'){
      if(!selection.event||!selection.eventBranch||!spec.selectionReason)throw new Error(`Repository policy selection evidence missing ${spec.id}`);
    }else if(!packages.length||packages.some(path=>!selection.affectedPackages.includes(path)))throw new Error(`Unrelated package selected ${spec.id}`);
    if((spec.family==='oxlint'||spec.task?.endsWith(':lint:oxlint'))&&(spec.executionScope!=='project'||spec.arguments?.length!==0||!spec.task?.endsWith(':lint:oxlint')))throw new Error(`Oxlint requires whole selected project ${spec.id}`);
  }
  const requested=instant(evidence.requestedAt),observed=instant(evidence.observedAt);
  if(observed<requested)throw new Error('Observation predates request');
  const manifest=new Map(evidence.manifest.map(row=>[row.id,row]));
  for(const row of evidence.checks)if(!manifest.has(row.id))throw new Error(`Unknown check ${row.id}`);
  const checks=new Map(evidence.checks.map(row=>[row.id,row]));
  const attempts=new Map(evidence.attempts.map(row=>[row.id,row]));
  const pending=new Set(manifest.keys()),distances=new Map();
  const outcomes=[];
  const waitIntervals=[];
  while(pending.size){
    let advanced=false;
    for(const id of pending){
      const spec=manifest.get(id);
      if((spec.needs??[]).some(dependency=>!manifest.has(dependency)))throw new Error(`Missing dependency for ${id}`);
      if((spec.needs??[]).some(dependency=>!distances.has(dependency)))continue;
      const result=checks.get(id);
      let elapsed=0;
      let policyDenied=false;
      if(result){
        if(spec.inputKind==='repository-policy'){
          if(spec.scope!=='repository'||!/^[a-f0-9]{40}$/.test(spec.policyRevision)||result.policyRevision!==spec.policyRevision||!/^[a-f0-9]{64}$/.test(spec.gateScriptSha256))throw new Error(`Repository policy identity differs ${id}`);
          const gate=result.policyEvidence?.gate;
          if(!gate||gate.executed!==true||gate.conclusion!=='success'||gate.scriptSha256!==spec.gateScriptSha256||typeof gate.allowed!=='boolean')throw new Error(`Repository policy gate evidence missing ${id}`);
          const observedHistory=instant(gate.historyObservedAt);
          if(observedHistory<requested||observedHistory>observed)throw new Error(`Policy observation outside request interval ${id}`);
          if(gate.allowed===false){
            if(result.conclusion!=='policy-denied'||result.policyEvidence.analysis?.executed!==false||result.policyEvidence.analysis?.conclusion!=='skipped'||!gate.reason)throw new Error(`Policy denial does not match analysis disposition ${id}`);
            policyDenied=true;
          }else{
            const analysis=result.policyEvidence.analysis;
            if(analysis?.executed!==true||analysis?.conclusion!==result.conclusion||!/^[a-f0-9]{40}$/.test(analysis?.observedCommit)||!analysis?.checks?.length)throw new Error(`Selected repository analysis evidence missing ${id}`);
          }
        }else if(result.revision!==evidence.revision)throw new Error(`Revision mismatch ${id}`);
        if(spec.family==='oxlint'||spec.task?.endsWith(':lint:oxlint')){
          if(result.invocation?.task!==spec.task||result.invocation?.executionScope!=='project'||result.invocation?.arguments?.length!==0)throw new Error(`Oxlint invocation evidence differs ${id}`);
        }
        for(const attemptId of result.attemptIds??[])if(!attempts.has(attemptId))throw new Error(`Unknown attempt ${attemptId}`);
        if(result.startedAt&&result.finishedAt){
          const started=instant(result.startedAt),finished=instant(result.finishedAt);
          if(started<requested||finished<started||finished>observed)throw new Error(`Invalid check interval ${id}`);
          elapsed=(finished-started)/1000;
          for(const dependency of spec.needs??[]){
            const prerequisite=checks.get(dependency);
            if(!prerequisite?.finishedAt||instant(prerequisite.finishedAt)>started)throw new Error(`Dependency chronology differs ${id}`);
          }
        }
      }
      const terminal=result?.finishedAt&&(['success','failure'].includes(result.conclusion)||policyDenied)&&result.executed===true;
      const accepted=terminal&&(result.conclusion==='success'||policyDenied)&&result.evidenceVerified===true&&(result.unexpectedSkips??0)===0;
      const stop=terminal?instant(result.finishedAt):observed;
      waitIntervals.push([requested,stop]);
      outcomes.push({id,state:!result?'missing':result.conclusion,terminal:Boolean(terminal),accepted:Boolean(accepted),censored:!terminal,policyDenied});
      distances.set(id,elapsed+Math.max(0,...(spec.needs??[]).map(dependency=>distances.get(dependency))));
      pending.delete(id);advanced=true;
    }
    if(!advanced)throw new Error('Cyclic manifest dependencies');
  }
  const compute={};
  const active=[];
  for(const attempt of evidence.attempts){
    if(attempt.revision!==evidence.revision)throw new Error(`Attempt revision mismatch ${attempt.id}`);
    if(!attempt.startedAt){if(attempt.finishedAt)throw new Error('Finish without start');continue;}
    const start=instant(attempt.startedAt),stop=attempt.finishedAt?instant(attempt.finishedAt):observed;
    if(stop<start||stop>observed)throw new Error(`Invalid attempt interval ${attempt.id}`);
    if(!(attempt.vcpus>0))throw new Error(`Missing resource size ${attempt.id}`);
    const seconds=(stop-start)/1000;
    const product=attempt.product;
    compute[product]??={seconds:0,vcpuSeconds:0,attempts:0,censoredAttempts:0};
    compute[product].seconds+=seconds;compute[product].vcpuSeconds+=seconds*attempt.vcpus;compute[product].attempts++;
    if(!attempt.finishedAt)compute[product].censoredAttempts++;
    active.push([start,stop]);
  }
  return {revision:evidence.revision,selection,manifestChecks:manifest.size,manifestComplete:evidence.manifestComplete===true,outcomes,accepted:evidence.manifestComplete===true&&outcomes.every(row=>row.accepted),allRequiredExecutedToTerminal:outcomes.every(row=>row.terminal),elapsedObservationSeconds:(observed-requested)/1000,unfinishedRequiredUnionSeconds:union(waitIntervals),activeAttemptUnionSeconds:union(active),executionDependencyPathSeconds:Math.max(0,...distances.values()),compute,limitations:['Provider execution intervals are usage proxies, not account ledger entries.','A missing, skipped, or cancelled required check remains censored at the observation boundary.','Execution dependency path excludes queue time and cannot replace observed request-to-completion time.','Selector reach is independently verified against repository changes; this reconciler validates its frozen output, not its discovery algorithm.']};
};
const output={inputSha256:createHash('sha256').update(raw).digest('hex'),...evaluate(input)};
writeFileSync(process.env.DEPOT_ACCOUNTING_OUTPUT??'analysis.json',JSON.stringify(output,null,2)+'\n');
console.log(JSON.stringify(output));
'''

[tasks.normalize]
shell = "node --input-type=module-typescript -e"
run = '''
const {readFileSync,writeFileSync} = await import('node:fs');
const {createHash} = await import('node:crypto');
const manifestPath=process.env.DEPOT_ACCOUNTING_MANIFEST,executionPath=process.env.DEPOT_ACCOUNTING_EXECUTION;
if(!manifestPath||!executionPath||!process.env.DEPOT_ACCOUNTING_REQUESTED_AT)throw new Error('Manifest, execution, and request timestamp required');
const raw=readFileSync(manifestPath),manifest=JSON.parse(raw),execution=JSON.parse(readFileSync(executionPath,'utf8'));
const digest=createHash('sha256').update(raw).digest('hex');
if(execution.manifestSha256!==digest)throw new Error('Executed manifest hash differs from supplied manifest');
if(execution.sourceRevision!==manifest.sourceRevision||manifest.sourceRevision!==manifest.headRevision)throw new Error('Source revision differs');
const specs=[...manifest.checks,...(manifest.externalChecks??[])];
const normalized=specs.map(spec=>({id:spec.id,needs:spec.prerequisites??[],task:spec.task,arguments:spec.args??[],family:spec.task?.endsWith(':lint:oxlint')?'oxlint':spec.family,scope:spec.scope,inputKind:spec.inputKind,policyRevision:spec.policyRevision,gateScriptSha256:spec.gateScriptSha256,packages:spec.packages??[],files:spec.files,selectionReason:spec.reason,executionScope:spec.scope==='package'||spec.scope==='project'?'project':spec.scope,expectedFiles:spec.expectedFiles,expectedFileCount:spec.expectedFileCount}));
const attempts=process.env.DEPOT_ACCOUNTING_ATTEMPTS?JSON.parse(readFileSync(process.env.DEPOT_ACCOUNTING_ATTEMPTS,'utf8')):[];
const checks=execution.results.map(row=>({id:row.checkId,revision:row.sourceRevision,policyRevision:row.policyRevision,policyEvidence:row.policyEvidence,startedAt:row.startedAt,finishedAt:row.finishedAt,elapsedMs:row.elapsedMs,conclusion:row.status==='passed'?'success':row.status==='failed'?'failure':row.status,executed:row.status==='passed'||row.status==='failed'||row.status==='policy-denied',evidenceVerified:row.evidenceVerified===true,unexpectedSkips:row.unexpectedSkips??0,attemptIds:row.attemptIds??execution.attemptIds??[],invocation:{task:row.task,arguments:row.args,executionScope:row.task?.endsWith(':lint:oxlint')?'project':undefined},skipReason:row.skipReason}));
const output={revision:manifest.headRevision,manifestComplete:manifest.completeGraph===true,requestedAt:process.env.DEPOT_ACCOUNTING_REQUESTED_AT,observedAt:process.env.DEPOT_ACCOUNTING_OBSERVED_AT??new Date().toISOString(),selection:{base:manifest.baseRevision,head:manifest.headRevision,event:manifest.event,eventBranch:manifest.eventBranch,changedFiles:manifest.changedFiles,affectedPackages:manifest.selectedPackages,excludedPackages:manifest.selectionEvidence?.negative??[],selectedCheckIds:specs.map(spec=>spec.id),manifestSha256:digest,excludedChecks:manifest.excludedChecks,selectionReasons:manifest.selectionReasons},manifest:normalized,checks,attempts};
writeFileSync(process.env.DEPOT_ACCOUNTING_OUTPUT??'normalized.json',JSON.stringify(output,null,2)+'\n');
console.log(JSON.stringify({revision:output.revision,selectedChecks:specs.length,recordedResults:checks.length,manifestComplete:output.manifestComplete}));
'''

[tasks.collect-github]
shell = "node --input-type=module-typescript -e"
run = '''
const {execFileSync} = await import('node:child_process');
const {mkdirSync,writeFileSync} = await import('node:fs');
const {createHash} = await import('node:crypto');
const {join} = await import('node:path');
const runId=process.env.DEPOT_ACCOUNTING_GITHUB_RUN;
if(!runId||!/^\d+$/.test(runId))throw new Error('DEPOT_ACCOUNTING_GITHUB_RUN must name one run');
const repo='Aquaticats/Monochromatic';
const dir=join(process.cwd(),`github-${runId}`);
mkdirSync(dir,{recursive:true,mode:0o700});
const get=(endpoint,name,paginate=false)=>{
  const raw=execFileSync('gh',['api',endpoint,...(paginate?['--paginate','--slurp']:[])],{encoding:'utf8',maxBuffer:64*1024*1024});
  writeFileSync(join(dir,name),raw);
  return JSON.parse(raw);
};
const repository=get(`repos/${repo}`,'repository.json');
const run=get(`repos/${repo}/actions/runs/${runId}`,'run.json');
if(process.env.DEPOT_ACCOUNTING_SHA&&run.head_sha!==process.env.DEPOT_ACCOUNTING_SHA)throw new Error('GitHub run revision mismatch');
const jobs=new Map();
for(let attempt=1;attempt<=run.run_attempt;attempt++){
  const pages=get(`repos/${repo}/actions/runs/${runId}/attempts/${attempt}/jobs?per_page=100`,`jobs-attempt-${attempt}.json`,true);
  const rows=pages.flatMap(page=>page.jobs);
  if(rows.length!==pages[0].total_count)throw new Error(`Incomplete job pagination attempt ${attempt}`);
  for(const job of rows){
    if(job.head_sha!==run.head_sha)throw new Error(`Job revision mismatch ${job.id}`);
    if(jobs.has(job.id))continue;
    const knownLabels=['ubuntu-latest','ubuntu-24.04','ubuntu-24.04-arm','windows-2025','windows-11-arm','macos-15-intel'];
    const label=job.labels.find(candidate=>knownLabels.includes(candidate));
    const allocation=label?{label,vcpus:label==='macos-15-intel'?4:repository.private?2:4,memoryGb:label==='macos-15-intel'?14:repository.private?8:16,publicStandardComputeUsd:repository.private?null:0,source:'https://docs.github.com/en/actions/reference/runners/github-hosted-runners#standard-github-hosted-runners-for-public-repositories'}:{label:null,vcpus:null,memoryGb:null,publicStandardComputeUsd:null};
    const record={id:job.id,attempt:job.run_attempt,workflow:run.name,name:job.name,status:job.status,conclusion:job.conclusion,headSha:job.head_sha,startedAt:job.started_at,completedAt:job.completed_at,seconds:job.completed_at&&job.started_at?(Date.parse(job.completed_at)-Date.parse(job.started_at))/1000:null,labels:job.labels,allocation,steps:job.steps};
    if(job.status==='completed'&&job.conclusion!=='skipped'){
      const log=execFileSync('gh',['api',`repos/${repo}/actions/jobs/${job.id}/logs`,'--allow-escape-sequences'],{encoding:'utf8',maxBuffer:64*1024*1024});
      const name=`logs-${job.id}.txt`;
      writeFileSync(join(dir,name),log);
      record.log={path:name,bytes:Buffer.byteLength(log),sha256:createHash('sha256').update(log).digest('hex')};
    }
    jobs.set(job.id,record);
  }
}
const summary={collectedAt:new Date().toISOString(),repo,visibility:repository.visibility,runId:run.id,revision:run.head_sha,runAttempt:run.run_attempt,status:run.status,conclusion:run.conclusion,createdAt:run.created_at,startedAt:run.run_started_at,updatedAt:run.updated_at,jobs:[...jobs.values()],scope:'Read-only repository execution metadata. Standard public runner compute is free under published policy; storage, account ledger, and nonstandard allocations are not inferred.'};
writeFileSync(join(dir,'collection.json'),JSON.stringify(summary,null,2)+'\n');
console.log(JSON.stringify({runId,revision:run.head_sha,jobs:jobs.size,status:run.status,visibility:repository.visibility,dir}));
'''

[tasks.verify]
shell = "node --input-type=module-typescript -e"
run = '''
const {execFileSync} = await import('node:child_process');
const {writeFileSync,readFileSync,mkdirSync} = await import('node:fs');
const {strictEqual,deepStrictEqual,throws} = await import('node:assert');
mkdirSync('fixtures',{recursive:true});
const revision='a'.repeat(40);
const at=seconds=>new Date(Date.UTC(2026,9,16)+seconds*1000).toISOString();
const base={revision,requestedAt:at(0),observedAt:at(40),manifest:[{id:'build',needs:[]},{id:'lint',needs:[]},{id:'test',needs:['build']}],checks:[{id:'build',revision,startedAt:at(5),finishedAt:at(15),conclusion:'success',executed:true,evidenceVerified:true,attemptIds:['shared']},{id:'lint',revision,startedAt:at(5),finishedAt:at(25),conclusion:'success',executed:true,evidenceVerified:true,attemptIds:['lint-job']},{id:'test',revision,startedAt:at(15),finishedAt:at(30),conclusion:'success',executed:true,evidenceVerified:true,attemptIds:['shared']}],attempts:[{id:'shared',revision,startedAt:at(3),finishedAt:at(32),product:'ci',vcpus:2},{id:'lint-job',revision,startedAt:at(4),finishedAt:at(27),product:'ci',vcpus:4}]};
base.manifestComplete=true;
base.selection={base:'b'.repeat(40),head:revision,changedFiles:['package/module/example/src/index.ts'],affectedPackages:['package/module/example'],excludedPackages:['package/module/unrelated'],selectedCheckIds:['build','lint','test'],manifestSha256:'c'.repeat(64)};
base.manifest=base.manifest.map(row=>({...row,packagePath:'package/module/example',...(row.id==='lint'?{family:'oxlint',executionScope:'project',task:'//package/module/example:lint:oxlint',arguments:[]}: {})}));
base.checks=base.checks.map(row=>row.id==='lint'?{...row,invocation:{task:'//package/module/example:lint:oxlint',executionScope:'project',arguments:[]}}:row);
const run=(name,input)=>{
  const path=`fixtures/${name}.json`,output=`fixtures/${name}.result.json`;
  writeFileSync(path,JSON.stringify(input,null,2));
  execFileSync('mise',['run','analyze'],{env:{...process.env,DEPOT_ACCOUNTING_INPUT:path,DEPOT_ACCOUNTING_OUTPUT:output},stdio:'pipe'});
  return JSON.parse(readFileSync(output,'utf8'));
};
const valid=run('valid',base);
strictEqual(valid.accepted,true);strictEqual(valid.unfinishedRequiredUnionSeconds,30);strictEqual(valid.activeAttemptUnionSeconds,29);strictEqual(valid.executionDependencyPathSeconds,25);strictEqual(valid.compute.ci.seconds,52);strictEqual(valid.compute.ci.vcpuSeconds,150);
const missing=run('missing',{...base,checks:base.checks.slice(0,2)});strictEqual(missing.accepted,false);strictEqual(missing.unfinishedRequiredUnionSeconds,40);
const cancelled=run('cancelled',{...base,checks:base.checks.map(row=>row.id==='test'?{...row,conclusion:'cancelled'}:row)});strictEqual(cancelled.accepted,false);strictEqual(cancelled.unfinishedRequiredUnionSeconds,40);
const failed=run('failed',{...base,checks:base.checks.map(row=>row.id==='lint'?{...row,conclusion:'failure'}:row)});strictEqual(failed.accepted,false);strictEqual(failed.allRequiredExecutedToTerminal,true);strictEqual(failed.unfinishedRequiredUnionSeconds,30);
const retry=run('retry',{...base,attempts:[...base.attempts,{id:'failed-first',revision,startedAt:at(1),finishedAt:at(3),product:'ci',vcpus:4}]});strictEqual(retry.compute.ci.vcpuSeconds,158);
const partial=run('partial-manifest',{...base,manifestComplete:false});strictEqual(partial.accepted,false);strictEqual(partial.allRequiredExecutedToTerminal,true);
const policySpec={id:'repository-policy',needs:[],scope:'repository',selectionReason:'main push policy',inputKind:'repository-policy',policyRevision:'d'.repeat(40),gateScriptSha256:'e'.repeat(64)};
const policyCheck={id:'repository-policy',policyRevision:'d'.repeat(40),startedAt:at(5),finishedAt:at(9),conclusion:'policy-denied',executed:true,evidenceVerified:true,policyEvidence:{gate:{executed:true,conclusion:'success',allowed:false,scriptSha256:'e'.repeat(64),historyObservedAt:at(8),reason:'hour budget exhausted'},analysis:{executed:false,conclusion:'skipped'}}};
const policyInput={...base,selection:{...base.selection,event:'push',eventBranch:'main',selectedCheckIds:[...base.selection.selectedCheckIds,policySpec.id]},manifest:[...base.manifest,policySpec],checks:[...base.checks,policyCheck]};
const policyDenied=run('policy-denied',policyInput);strictEqual(policyDenied.accepted,true);strictEqual(policyDenied.outcomes.find(row=>row.id==='repository-policy').policyDenied,true);
const policySelectedInput={...policyInput,checks:[...base.checks,{...policyCheck,conclusion:'success',policyEvidence:{gate:{...policyCheck.policyEvidence.gate,allowed:true},analysis:{executed:true,conclusion:'success',observedCommit:'f'.repeat(40),checks:['Maintained']}}}]};
const policySelected=run('policy-selected-analysis',policySelectedInput);strictEqual(policySelected.accepted,true);
const rejected=[['duplicate-attempt',{...base,attempts:[...base.attempts,base.attempts[0]]}],['wrong-revision',{...base,checks:base.checks.map(row=>({...row,revision:'b'.repeat(40)}))}],['cyclic',{...base,manifest:base.manifest.map(row=>row.id==='build'?{...row,needs:['test']}:row)}],['unknown-check',{...base,checks:[...base.checks,{...base.checks[0],id:'unlisted'}]}]];
rejected.push(['missing-selected-check',{...base,manifest:base.manifest.slice(0,2)}],['unrelated-package',{...base,manifest:base.manifest.map(row=>row.id==='test'?{...row,packagePath:'package/module/unrelated'}:row)}],['oxlint-file-filter',{...base,manifest:base.manifest.map(row=>row.id==='lint'?{...row,arguments:['src/index.ts']}:row)}],['oxlint-file-mode',{...base,manifest:base.manifest.map(row=>row.id==='lint'?{...row,executionScope:'file'}:row)}]);
rejected.push(['empty-manifest',{...base,manifest:[],checks:[],selection:{...base.selection,selectedCheckIds:[]}}]);
